L5_1.m_Face = "UNIT_LAUGH"
L5_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L5_1.m_Pos = "L"
L5_1.m_Talk_KOREA = "놀이 공원 진짜 오랜만이거든요. 어렸을 때 한 번 왔던 거 빼고 처음이에요."
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "遊園地、本当に久しぶりだったんです。小さい頃一度来たきりだったので。"
L5_1.m_Talk_ENG = "It’s been so long since I last visited an amusement park. I only went once when I was a child."
L5_1.m_Talk_TWN = "好久沒來遊樂園了，我只有小時候來過一次，後來就沒來過了。"
L5_1.m_Talk_THA = "นานมากแล้วตั้งแต่ฉันไปสวนสนุกครั้งสุดท้าย เคยไปครั้งเดียวตอนเด็กๆ"
L5_1.m_Talk_VTN = "Đã lâu rồi cháu không đi công viên giải trí. Cháu chỉ đi một lần khi còn nhỏ."
L5_1.m_Talk_SCN = "好久没来过游乐园了。我记得我只在小时候来过一次呢。"
L5_1.m_Talk_DEU = "Ich war nämlich echt lange nicht mehr in einem Themenpark. Das letzte Mal war, als ich klein war."
L5_1.m_Talk_FRA = "Ça faisait longtemps que je n'étais pas venue dans un parc d'attraction. Quand j'étais petite j'y allais souvent, pourtant..."
