L7_1.m_Face = "UNIT_IDLE"
L7_1.m_CharStrID = "INGRID_STREGA_NULL_NULL"
L7_1.m_Pos = "C"
L7_1.m_Talk_KOREA = "쳇, 조금만 더 시간이 있었으면 귀신의 집에 있는 귀신들을 다 쓰러트릴 수 있었는데."
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "ちえっ、もう少し時間があればお化け屋敷のやつら全員やっつけられたのに。"
L7_1.m_Talk_ENG = "Darn, I could have defeated all the ghosts in the haunted house if I had more time."
L7_1.m_Talk_TWN = "嘖，時間不夠啦，我都還沒打倒那些鬼屋裡的鬼欸！"
L7_1.m_Talk_THA = "ให้ตายเถอะ ฉันน่าจะเอาชนะผีทั้งหมดในบ้านผีสิงได้ถ้าฉันมีเวลามากกว่านี้"
L7_1.m_Talk_VTN = "Chết tiệt, mình có thể đánh bại tất cả những con ma trong ngôi nhà ma ám nếu có thêm thời gian."
L7_1.m_Talk_SCN = "切，如果再给我一点时间，我就能把鬼屋里边的鬼怪都打倒。"
L7_1.m_Talk_DEU = "Hmpf, hätte ich etwas mehr Zeit gehabt, hätte ich alle Gespenster im Geisterhaus besiegen können."
L7_1.m_Talk_FRA = "Bah, je voulais aller dans le manoir hanté pour éliminer tous les fantômes ! Mais on a pas le temps..."
