L12_1.m_Pos = "R"
L12_1.m_Talk_KOREA = "남의 장사 거덜 낼 일 있어? 귀신의 집에서 일하는 귀신을 때리면 하면 어떡해?"
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "人に迷惑ばかりかけて！　お化け屋敷で働く人を殴ってどうする！"
L12_1.m_Talk_ENG = "You almost ruined their business! Why did you hit them?"
L12_1.m_Talk_TWN = "幹嘛妨礙人家做生意？沒事打鬼屋裡的工讀生幹嘛？"
L12_1.m_Talk_THA = "คุณเกือบจะทำลายธุรกิจของพวกเขา! ทำไมคุณถึงตีพวกเขา?"
L12_1.m_Talk_VTN = "Cô gần như đã hủy hoại công việc của họ! Tại sao lại đánh họ?"
L12_1.m_Talk_SCN = "你是想把别人的生意搅黄吗？怎么可以打在鬼屋工作的鬼怪呢？"
L12_1.m_Talk_DEU = "Willst du, dass sie Pleite gehen? Du kannst doch nicht die Gespenster hauen, die im Geisterhaus arbeiten!"
L12_1.m_Talk_FRA = "Tu veux que ce parc mette la clé sous la porte ? Pourquoi tu veux éliminer tous les fantômes de la maison hantée ?"
L13_1 = {}
L13_1.m_CutScenKey_Talk = "COUNTERCASE_YUNA_NORMAL_3@13#Talk"
L13_1.m_CutScenProcessKey = 13
