L13_1.m_Crash = 20
L13_1.m_Talk_KOREA = "나, 나는 진짜 귀신인 줄 알았다니깐!"
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "わ、私は本物のお化けかと思っただけなの！"
L13_1.m_Talk_ENG = "I-I thought they were real ghosts!"
L13_1.m_Talk_TWN = "我…我還以為他們是真的鬼嘛！"
L13_1.m_Talk_THA = "ฉันนึกว่าพวกมันเป็นผีจริงๆ!"
L13_1.m_Talk_VTN = "Tôi tưởng họ là ma thật!"
L13_1.m_Talk_SCN = "我、我还以为是真的鬼怪！"
L13_1.m_Talk_DEU = "I-ich dachte, das seien echte Geister!"
L13_1.m_Talk_FRA = "M-Mais je croyais que c'était des vrais fantômes, moi !"
