L15_1.m_Talk_KOREA = "후훗, 다들 즐거워 보여서 다행이네."
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "ふふっ。みんな楽しんでくれたようでよかったわ。"
L15_1.m_Talk_ENG = "Haha, I’m glad to see you’re all enjoying yourselves."
L15_1.m_Talk_TWN = "呵呵，大家玩得開心就好。"
L15_1.m_Talk_THA = "ฮ่าๆ ดีใจที่เห็นทุกคนสนุกกันนะคะ"
L15_1.m_Talk_VTN = "Haha, tôi rất vui khi thấy tất cả đều vui vẻ."
L15_1.m_Talk_SCN = "吼吼。你们看起来都很高兴，太好了。"
L15_1.m_Talk_DEU = "Hehe, ich bin froh, dass alle so viel Spaß haben."
L15_1.m_Talk_FRA = "Je suis ravie de voir que vous êtes toutes de bonne humeur."
