L18_1.m_Pos = "L"
L18_1.m_Talk_KOREA = "근데 에블린 언니, 놀이 공원 티켓은 어떻게 공짜로 얻은 거예요? 그것도 네 장씩이나."
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "ところでエヴリン姉さん、遊園地のチケットをタダで貰ったって、どうしたんですか？\nしかも4枚も。"
L18_1.m_Talk_ENG = "By the way, Evelyn, where did you get all the free tickets?"
L18_1.m_Talk_TWN = "不過伊芙琳姊姊，為什麼你會有免費的門票，而且還四張欸？"
L18_1.m_Talk_THA = "ว่าแต่ อีฟลิน คุณได้ตั๋วฟรีทั้งหมดมาจากไหน?"
L18_1.m_Talk_VTN = "Nhân tiện, Evelyn, cô lấy đâu ra tất cả vé miễn phí vậy?"
L18_1.m_Talk_SCN = "可是伊芙琳姐姐，你是怎么免费拿到游乐园门票的？还一下子拿到了四张？"
L18_1.m_Talk_DEU = "Aber Evelyn, woher hast du die Eintrittskarten für den Themenpark kostenlos bekommen? Und das auch noch vier Stück?"
L18_1.m_Talk_FRA = "Au fait Evelyn, comment as-tu fait pour avoir ces billets ? Quatre entrées gratuites, c'est pas rien !"
L19_1 = {}
L19_1.m_CutScenKey_Talk = "COUNTERCASE_YUNA_NORMAL_3@19#Talk"
L19_1.m_CutScenProcessKey = 19
L19_1.m_CutScenID = 30913
