L19_1.m_Crash = 30
L19_1.m_Talk_KOREA = "아하, 이거?"
L19_1.m_fTalkTime = 0.03
L19_1.m_Talk_JPN = "ああ、これね。"
L19_1.m_Talk_ENG = "Oh, these?"
L19_1.m_Talk_TWN = "哈哈，你說這個嗎？"
L19_1.m_Talk_THA = "โอ้เหล่านี้?"
