L20_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L20_1.m_Pos = "R"
L20_1.m_Talk_KOREA = "사실 원래 티켓을 얻게 된 건 몇 개월 전이야."
L20_1.m_fTalkTime = 0.03
L20_1.m_Talk_JPN = "実はチケットをもらったのは、数ヶ月も前のことなんだけど。"
L20_1.m_Talk_ENG = "I actually bought a ticket a few months ago."
L20_1.m_Talk_TWN = "其實我在幾個月前就拿到門票了。"
L20_1.m_Talk_THA = "จริงๆ แล้วฉันซื้อตั๋วเมื่อสองสามเดือนก่อน"
L20_1.m_Talk_VTN = "Thực ra ta đã mua vé cách đây vài tháng."
L20_1.m_Talk_SCN = "其实门票是在几个月前拿到的。"
L20_1.m_Talk_DEU = "Eigentlich hatte ich schon vor einigen Monaten Tickets."
L20_1.m_Talk_FRA = "En fait, j'avais acheté des billets il y a quelques mois."
