L21_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L21_1.m_Pos = "R"
L21_1.m_Talk_KOREA = "갑작스러운 대규모 침식 재난으로 놀이 공원이 문을 닫는 바람에 못 쓰게 됐지, 뭐야?"
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "突然の大規模侵食災害で遊園地が閉鎖しちゃって、有効期限が切れてしまったの。"
L21_1.m_Talk_ENG = "But then a large-scale Corruption disaster happened, so the amusement park had to close for a while."
L21_1.m_Talk_TWN = "只是突然發生大規模侵蝕災難，導致遊樂園暫停營業，所以也沒辦法來。"
L21_1.m_Talk_THA = "แต่แล้วเกิดภัยพิบัติคอร์รัปชันครั้งใหญ่ สวนสนุกจึงต้องปิดตัวลงชั่วคราว"
L21_1.m_Talk_VTN = "Nhưng rồi thảm họa Ăn Mòn quy mô lớn xảy ra nên khu vui chơi phải đóng cửa một thời gian."
L21_1.m_Talk_SCN = "因为突发的侵蚀灾难，游乐园停止营业，所以没能用上。"
L21_1.m_Talk_DEU = "Aber aufgrund einer plötzlichen Verderbniskatastrophe von einem großen Ausmaß musste der Themenpark schließen und die Karten wurden nutzlos."
L21_1.m_Talk_FRA = "Mais je n'ai pas pu les utiliser jusqu'à maintenant, car le parc était fermé à cause d'un sinistre causé par la corruption."
L22_1 = {}
L22_1.m_CutScenKey_Talk = "COUNTERCASE_YUNA_NORMAL_3@22#Talk"
L22_1.m_CutScenProcessKey = 22
L22_1.m_CutScenID = 30913
L22_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_3"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L22_1.m_Pos = "R"
L22_1.m_Talk_KOREA = "그런데 이번에 다시 개장하면서 사과의 의미로 공짜 티켓을 네 장이나 받게 된 거지."
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "だけど営業再開することになって、お詫びとしてチケットを4枚もらえたのよ。"
L22_1.m_Talk_ENG = "When they reopened, they gave me four free tickets as compensation."
L22_1.m_Talk_TWN = "遊樂園想這次趁著改裝順便補償之前沒能用到門票的客人，所以我就獲得四張囉。"
L22_1.m_Talk_THA = "เมื่อพวกเขาเปิดอีกครั้ง พวกเขาให้ตั๋วฟรีสี่ใบแก่ฉันเป็นการชดเชย"
L22_1.m_Talk_VTN = "Khi họ mở cửa trở lại, họ đã bồi thường cho ta bốn vé miễn phí."
L22_1.m_Talk_SCN = "不过幸好又重新开业了，所以拿到了四张免费门票当作补偿。"
L22_1.m_Talk_DEU = "Neulich haben sie aber neu eröffnet. Als Wiedergutmachung habe ich ganze vier Tickets kostenlos bekommen."
L22_1.m_Talk_FRA = "Alors en compensation, le gérant m'a donné ces billets gratuits. Une façon pour lui de célébrer la réouverture du lieu !"
L23_1 = {}
L23_1.m_CutScenKey_Talk = "COUNTERCASE_YUNA_NORMAL_3@23#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 30913
L23_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_3"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_Face = "UNIT_IDLE"
L23_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L23_1.m_Pos = "L"
L23_1.m_Talk_KOREA = "아하, 뉴스에서 본 적 있어요! 카운터 총동원령이 내려졌을 때구나."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "あ、ニュースで見ました！　カウンター総動員令が出た時ですね。"
L23_1.m_Talk_ENG = "Oh, I remember. That’s when they mobilized all Counters."
L23_1.m_Talk_TWN = "喔喔！我有看過新聞！就是制裁者總動員那次嗎？"
L23_1.m_Talk_THA = "โอ้ ฉันจำได้ นั่นคือตอนที่พวกเขาระดมเคาน์เตอร์ทั้งหมด"
L23_1.m_Talk_VTN = "Ồ, cháu nhớ rồi. Đó là lúc họ huy động tất cả các Counter."
L23_1.m_Talk_SCN = "啊哈，我好像在新闻上看到过！是下达制裁者总动员令的时候。"
L23_1.m_Talk_DEU = "Aha, das habe ich in den Nachrichten gesehen! Das war zu der Zeit, als alle Counter gleichzeitig in den Einsatz geschickt wurden."
L23_1.m_Talk_FRA = "Ah oui, je crois que j'ai vu ça aux informations ! Tous les Counters avaient été mobilisés, non ?"
