L25_1.m_Face = "UNIT_LAUGH"
L25_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L25_1.m_Pos = "C"
L25_1.m_Crash = 30
L25_1.m_Talk_KOREA = "헤헤… 그때만 해도 제가 이렇게 마녀가 될 줄은 꿈에도 상상 못했는데."
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "へへ……あの時は私が魔女になるなんて夢にも思わなかったな。"
L25_1.m_Talk_ENG = "Hehe. I never knew I was going to be a witch back then."
L25_1.m_Talk_TWN = "嘿嘿…那時候我連做夢都沒想過我會變成魔女呢？"
L25_1.m_Talk_THA = "ฮิฮิ. ฉันไม่เคยรู้เลยว่าฉันจะเป็นแม่มดในตอนนั้น"
L25_1.m_Talk_VTN = "Hehe. Lúc đó cháu chưa bao giờ biết mình sẽ trở thành phù thủy."
L25_1.m_Talk_SCN = "嘿嘿……那时候我做梦都没想到自己会成为魔女。"
L25_1.m_Talk_DEU = "Hehe ... Damals habe ich mir noch nicht zu träumen gewagt, dass aus mir eine Hexe wird."
L25_1.m_Talk_FRA = "Hé hé... À l'époque, je n'aurais jamais pensé devenir une sorcière."
