L28_1.m_Talk_KOREA = "아직 견습이지만."
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "まだ見習いだがな。"
L28_1.m_Talk_ENG = "You’re still in training, though."
L28_1.m_Talk_TWN = "還在實習階段啦。"
L28_1.m_Talk_THA = "คุณยังอยู่ระหว่างการฝึก"
L28_1.m_Talk_VTN = "Tuy nhiên, nhóc vẫn đang trong quá trình đào tạo."
L28_1.m_Talk_SCN = "现在也只是见习而已。"
L28_1.m_Talk_DEU = "Beziehungsweise ein Lehrling."
L28_1.m_Talk_FRA = "Une apprentie sorcière, tu veux dire ?"
L29_1 = {}
L29_1.m_CutScenKey_Talk = "COUNTERCASE_YUNA_NORMAL_3@29#Talk"
L29_1.m_CutScenProcessKey = 29
L29_1.m_CutScenID = 30913
