L29_1.m_Pos = "L"
L29_1.m_Crash = 30
L29_1.m_Talk_KOREA = "…읏, 너무해! 라우라."
L29_1.m_fTalkTime = 0.03
L29_1.m_Talk_JPN = "うう、ひどい、ラウラ！"
L29_1.m_Talk_ENG = "Aww, don’t ruin the mood, Laura."
L29_1.m_Talk_TWN = "…蘿拉你很討厭欸！"
L29_1.m_Talk_THA = "อุ๊ย อย่าทำลายอารมณ์นะ ลอร่า"
L29_1.m_Talk_VTN = "Ôi, đừng phá hỏng không khí thế, Laura."
L29_1.m_Talk_SCN = "……呃，太过分了吧！劳拉。"
L29_1.m_Talk_DEU = "... Urgh, wie gemein, Laura!"
L29_1.m_Talk_FRA = "T'es méchante, Laura !"
L30_1 = {}
L30_1.m_CutScenKey_Talk = "COUNTERCASE_YUNA_NORMAL_3@30#Talk"
L30_1.m_CutScenProcessKey = 30
L30_1.m_CutScenID = 30913
L30_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_3"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_Face = "UNIT_IDLE"
L30_1.m_CharStrID = "LAURA_STREGA_EVENT_NULL"
L30_1.m_Pos = "R"
L31_1 = "…아무튼 이걸로 직원 복지는 이걸로 충분하지? 내일부터는 다시 마법 훈련 시작이야."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "……とにかく、これで福利厚生は十分だろう？\n明日からはまた魔法訓練が待ってるからな。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Anyway, this was a nice employee outing, right? We will start training again tomorrow."
L30_1.m_Talk_ENG = L31_1
L31_1 = "…總之這就是你們的員工福利，玩夠了吧？明天要繼續訓練魔法知道嗎？"
L30_1.m_Talk_TWN = L31_1
L31_1 = "อย่างไรก็ตาม นี่เป็นการออกนอกบ้านของพนักงานที่ดีใช่ไหม? เราจะเริ่มฝึกซ้อมอีกครั้งพรุ่งนี้"
L30_1.m_Talk_THA = L31_1
L31_1 = "Dù sao thì đây cũng là một chuyến đi chơi vui vẻ của nhân viên phải không? Chúng ta sẽ bắt đầu tập luyện trở lại vào ngày mai."
L30_1.m_Talk_VTN = L31_1
L31_1 = "……总之，这样就算发放过职员福利了吧？明天开始又要进行魔法训练。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "... Jedenfalls reicht das als Mitarbeiterbonus, oder? Ab morgen geht‘s wieder ans Magie-Training."
L30_1.m_Talk_DEU = L31_1
L31_1 = "... De quoi tu te plains ? Il y a pire comme avantage de salarié, non ? Demain, on reprend l'entraînement !"
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "COUNTERCASE_YUNA_NORMAL_3@31#Talk"
