L31_1.m_Pos = "L"
L32_1 = "…자, 잠깐만! 아직, 아직 아니야!"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "……ま、待って！　まだ、まだなの！"
L31_1.m_Talk_JPN = L32_1
L32_1 = "W-wait! Not just yet!"
L31_1.m_Talk_ENG = L32_1
L32_1 = "…先等一下！還沒玩夠啦！"
L31_1.m_Talk_TWN = L32_1
L32_1 = "ค-รอก่อน! ยังไม่หมดเพียงเท่านั้น!"
L31_1.m_Talk_THA = L32_1
L32_1 = "Đ-đợi đã! Không được!"
L31_1.m_Talk_VTN = L32_1
L32_1 = "……等、等等！还、还没完呢！"
L31_1.m_Talk_SCN = L32_1
L32_1 = "... M-moment! Noch nicht, noch nicht!"
L31_1.m_Talk_DEU = L32_1
L32_1 = ".. N-Non ! Attends ! Pas déjà..."
L31_1.m_Talk_FRA = L32_1
