L35_1 = "여기 귀신의 집에서만 살 수 있는 1인 1개 한정 초콜릿 케이크가 있거든!"
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "ここのお化け屋敷でしか買えない、1人1個までの限定チョコレートケーキがあるの！"
L34_1.m_Talk_JPN = L35_1
L35_1 = "They sell limited edition cakes at the haunted house, only one per person!"
L34_1.m_Talk_ENG = L35_1
L35_1 = "鬼屋有賣一人限購一份的巧克力蛋糕!"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ที่นี่ขายเค้กรุ่นลิมิเต็ดอิดิชั่นที่บ้านผีสิง คนละ 1 ชิ้นเท่านั้น!"
L34_1.m_Talk_THA = L35_1
L35_1 = "Họ bán những chiếc bánh phiên bản giới hạn tại ngôi nhà ma ám, mỗi người chỉ có một chiếc!"
L34_1.m_Talk_VTN = L35_1
L35_1 = "可以在这边的鬼屋买到每人限定一份的巧克力蛋糕！"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Hier im Geisterhaus gibt es nämlich einen Schokokuchen, der auf ein Stück pro Person limitiert ist!"
L34_1.m_Talk_DEU = L35_1
L35_1 = "Je veux absolument ce gâteau au chocolat qu'on ne vend que dans le manoir hanté ! Ce n'est qu'un achat par personne..."
L34_1.m_Talk_FRA = L35_1
