L7_1.m_CharStrID = L8_1
L7_1.m_Pos = "C"
L8_1 = "네. 혹시 일행 분 있으세요? 1인 1구매가 원칙이긴 한데."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "はい。お連れの方はいらっしゃいませんか？　原則1人1個までなんですが……"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Yes. Did you bring a friend with you? We only sell one per person."
L7_1.m_Talk_ENG = L8_1
L8_1 = "是的，請問你是和朋友一起來的嗎？原則上是一人限購一個。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ใช่ คุณพาเพื่อนมาด้วยหรือเปล่า? เราขายเพียงหนึ่งต่อคนเท่านั้น"
L7_1.m_Talk_THA = L8_1
L8_1 = "Đúng. Cô có mang theo một người bạn phải không? Chúng tôi chỉ bán mỗi người một cái."
L7_1.m_Talk_VTN = L8_1
L8_1 = "是的，你有一起来的同伴吗？虽然规定是限定每人一份。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Ja. Sind Sie vielleicht mit Begleitung hier? Prinzipiell gilt: ein Kuchen pro Kopf."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Oui. Vous êtes venue avec des amis ? C'est un seul gâteau par personne mais..."
L7_1.m_Talk_FRA = L8_1
