L9_1 = "사실, 구매를 안 하신 분이 구매하셔서 양도하는 건 상관 없거든요."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "まだご購入されていない方が買って、他の方にお譲りするのは構いませんので。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "You can ask your friend to buy it for you if you want them both."
