L9_1 = "不過要是請朋友代購也是可以的。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "คุณสามารถขอให้เพื่อนของคุณซื้อให้คุณถ้าคุณต้องการทั้งสองอย่าง"
L8_1.m_Talk_THA = L9_1
L9_1 = "cô có thể nhờ bạn mua hộ nếu muốn cả hai."
L8_1.m_Talk_VTN = L9_1
L9_1 = "但如果有没买过的人转让资格给你，就不受限制。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Aber es ist erlaubt, dass man weitere kauft und sie weitergibt."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Je peux faire une exception si vous souhaitez le donner à quelqu'un qui n'a pas encore acheté le sien."
L8_1.m_Talk_FRA = L9_1
