L17_1 = "무, 물론... 빨리 팔아버리고 쉬고 싶어서 그런 건 절대 아니고요. 아하하."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "け、決して早く売り切っちゃって休みたいわけではないですから、あはは。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "O-of course it’s not that I want to sell them all at once and take a break... Haha."
L16_1.m_Talk_ENG = L17_1
L17_1 = "雖然…我個人是很想趕快賣光回家休息啦，不過顧客至上。哈哈哈。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "โอ-แน่นอนว่าไม่ใช่ว่าอยากขายหมดทีเดียวแล้วพักซะก่อน... 555"
L16_1.m_Talk_THA = L17_1
L17_1 = "T-tất nhiên không phải là tôi muốn bán hết chúng cùng một lúc rồi nghỉ đâu... Haha."
L16_1.m_Talk_VTN = L17_1
