L20_1 = "무슨 헛소리야, 그깟 케이크 하나 샀으면 됐지, 뭘 또 산다는 거야?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "何を言ってるんだ？　そんなケーキ、1個あればもう十分だろう。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "What? You already have a cake, why would you need another?"
L19_1.m_Talk_ENG = L20_1
L20_1 = "買一個就好，為什麼要買二個？"
L19_1.m_Talk_TWN = L20_1
L20_1 = "อะไร คุณมีเค้กอยู่แล้ว แล้วทำไมคุณถึงต้องการเค้กอีกล่ะ?"
L19_1.m_Talk_THA = L20_1
L20_1 = "Cái gì? Nhóc đã có một chiếc bánh rồi, tại sao lại cần một chiếc bánh nữa?"
L19_1.m_Talk_VTN = L20_1
L20_1 = "你别胡闹了。买到一份不就可以了吗，为什么又要买一份？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Was für ein Quatsch! Ein Kuchen reicht doch schon, wozu willst du denn noch was kaufen?"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Qu'est-ce que tu racontes ! Tu en a déjà un, ça ne te suffit pas ?"
L19_1.m_Talk_FRA = L20_1
