L25_1 = "여기 오싹오싹 호박 초콜릿 케이크 하나 주시겠어요?"
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "あの、ゾクゾクかぼちゃのチョコレートケーキを１つください。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Hello, I would like a Creepy Pumpkin Chocolate cake, please."
L24_1.m_Talk_ENG = L25_1
L25_1 = "你好，我想要一個恐怖喔南瓜巧克力蛋糕。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "สวัสดีครับ ผมขอเค้กช็อคโกแลตฟักทองที่น่าขนลุกครับ"
L24_1.m_Talk_THA = L25_1
L25_1 = "Xin chào, tôi muốn một chiếc bánh sô cô la bí ngô đáng sợ."
L24_1.m_Talk_VTN = L25_1
L25_1 = "能给我一份惊悚南瓜巧克力蛋糕吗？"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Ich hätte gerne einen Schokokuchen des gruseligen Kürbisgeistes!"
L24_1.m_Talk_DEU = L25_1
