L26_1 = "으앗! 이러다 다 팔리겠어!! 어떡하지!?"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "うわっ！　このままじゃすぐ売り切れちゃう！　どうしよう。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Oh no! They might be sold out! What do I do?"
L25_1.m_Talk_ENG = L26_1
L26_1 = "糟糕！不趕快買的話會被賣掉的！！怎麼辦！？"
L25_1.m_Talk_TWN = L26_1
L26_1 = "ไม่นะ! มันอาจจะขายหมดแล้ว! ฉันจะทำอย่างไร?"
L25_1.m_Talk_THA = L26_1
L26_1 = "Ôi không! Chúng sẽ bị bán hết mất! Làm sao giờ？"
L25_1.m_Talk_VTN = L26_1
L26_1 = "呃啊！这样下去会卖光的！该怎么办！？"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Uah! Gleich sind sie ausverkauft! Was nun?!"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Oh non ! À ce rythme, les gâteaux seront bientôt tous vendus ! Que faire..."
