L35_1 = "COUNTERCASE_YUNA_NORMAL_3@84#Talk"
L34_1.m_CutScenKey_Talk = L35_1
L35_1 = 84
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 30913
L34_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_3"
L34_1.m_bWaitClick = true
L34_1.m_fWaitTime = 0
L34_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L35_1 = "솔라코덱스를 펼치면, 어쩐지 키도 커지고 분위기도 어른스러워진다고."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "ソーラーコーデックスを開けば、なんだか背が伸びて雰囲気まで大人っぽくなるって。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "That I look taller and more mature when I use the Solar Codex."
L34_1.m_Talk_ENG = L35_1
L35_1 = "展開太陽法典後，不只會長高，還會變得像大人一樣。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "ฉันดูสูงและเป็นผู้ใหญ่มากขึ้นเมื่อใช้โซลาร์โคเด็กซ์"
L34_1.m_Talk_THA = L35_1
L35_1 = "Rằng mình trông cao hơn và trưởng thành hơn khi sử dụng Solar Codex."
L34_1.m_Talk_VTN = L35_1
L35_1 = "如果开启太阳法典，个子就会变高，看起来就会像大人一样。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Wenn man den Solarkodex aufschlägt, soll man irgendwie größer und erwachsener werden."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Que celui ou celle ouvre le Codex solaire pouvait grandir et avoir une allure d'adulte."
L34_1.m_Talk_FRA = L35_1
L35_1 = {}
L36_1 = "COUNTERCASE_YUNA_NORMAL_3@85#Talk"
L35_1.m_CutScenKey_Talk = L36_1
L36_1 = 85
L35_1.m_CutScenProcessKey = L36_1
L35_1.m_CutScenID = 30913
L35_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_3"
L35_1.m_bWaitClick = true
L35_1.m_fWaitTime = 0
L35_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L36_1 = "그런데 이런 일로 솔라코덱스를 펼쳐도 되는 걸까? 레일리가 잔소리할 게 뻔한데……."
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "でもこんなことでソーラーコーデックスを開いてもいいのかな？　レイリーに怒られるよね……"
L35_1.m_Talk_JPN = L36_1
L36_1 = "But is it okay to use the Solar Codex for this? Rayleigh will nag at me for sure."
L35_1.m_Talk_ENG = L36_1
L36_1 = "可是可以因為這種事展開太陽法典嗎？瑞利肯定會罵人的吧……"
L35_1.m_Talk_TWN = L36_1
L36_1 = "แต่จะใช้โซลาร์โคเด็กซ์เพื่อสิ่งนี้ได้หรือไม่ เรย์ลีจะดุฉันแน่นอน"
L35_1.m_Talk_THA = L36_1
L36_1 = "Nhưng sử dụng Solar Codex cho việc này có ổn không? Rayleigh chắc chắn sẽ cằn nhằn."
L35_1.m_Talk_VTN = L36_1
L36_1 = "可是为了这种事开启太阳法典没关系吗？雷利应该又会唠叨吧……"
L35_1.m_Talk_SCN = L36_1
L36_1 = "Aber darf ich wegen so einer Sache den Solarkodex aufschlagen? Rayleigh wird garantiert meckern ..."
L35_1.m_Talk_DEU = L36_1
L36_1 = "Mais est-ce une bonne idée de l'ouvrir juste pour ça ? Rayleigh va certainement me faire la morale..."
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
