L48_1 = "유나, 이 녀석!! 겨우 이런 일로 솔라코덱스를 펼쳐!?"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "お前！！　そんな理由でソーラーコーデックスを開いたのか！？"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Yuna, you used the Solar Codex to get more cakes?!"
L47_1.m_Talk_ENG = L48_1
L48_1 = "尤娜，你這傢伙！！竟然因為這種事就展開太陽法典！？"
L47_1.m_Talk_TWN = L48_1
L48_1 = "ยูนา เธอใช้โซลาร์โคเด็กซ์เพื่อรับเค้กเพิ่มเหรอ?!"
L47_1.m_Talk_THA = L48_1
L48_1 = "Yuna, nhóc đã sử dụng Solar Codex để mua thêm bánh?!"
L47_1.m_Talk_VTN = L48_1
L48_1 = "尤娜，你这家伙！！竟然因为这种事，就随便开启太阳法典！？"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Also wirklich, Yuna!!! Nur wegen so einer Lappalie schlägst du den Solarkodex auf?!"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Yuna ! Tu te moques de moi ? Tu as ouvert le Codex solaire juste pour ça ?"
L47_1.m_Talk_FRA = L48_1
