L49_1 = "RAYLEIGH_CODEX_NULL_NULL"
L48_1.m_CharStrID = L49_1
L49_1 = "솔라코덱스가 얼마나 위험한 물건인 줄 알아??"
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "ソーラーコーデックスがどれだけ危険なものか、知ってるよな！？"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Do you have any idea how dangerous that is?"
L48_1.m_Talk_ENG = L49_1
L49_1 = "你知道太陽法典有多危險嗎？？"
L48_1.m_Talk_TWN = L49_1
L49_1 = "คุณรู้ไหมว่ามันอันตรายแค่ไหน?"
L48_1.m_Talk_THA = L49_1
L49_1 = "Có biết điều đó nguy hiểm thế nào không?"
L48_1.m_Talk_VTN = L49_1
L49_1 = "你知道太阳法典是多危险的东西吗？"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Du hast keine Ahnung, wie gefährlich der Solarkodex sein kann!!!"
L48_1.m_Talk_DEU = L49_1
L49_1 = "Tu sais à quel point cet objet est dangereux ?"
L48_1.m_Talk_FRA = L49_1
