L50_1 = "RAYLEIGH_CODEX_NULL_NULL"
L49_1.m_CharStrID = L50_1
L50_1 = "제어 유닛인 이 몸의 보조가 없었으면, 지금쯤 넌 벌써 통구이가 되어 있을 거다!!"
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "制御ユニットである俺がいなかったら、今頃お前は丸焦げだぞ！！"
L49_1.m_Talk_JPN = L50_1
L50_1 = "If I wasn’t here to serve as a control unit, you would have been roasted alive!"
L49_1.m_Talk_ENG = L50_1
L50_1 = "要不是有我這個法典控制者的輔助，你早就被烤焦了！！"
L49_1.m_Talk_TWN = L50_1
L50_1 = "ถ้าฉันไม่ได้มาที่นี่เพื่อทำหน้าที่เป็นหน่วยควบคุม คุณคงถูกย่างทั้งเป็น!"
L49_1.m_Talk_THA = L50_1
L50_1 = "Nếu tôi không ở đây làm đơn vị điều khiển thì nhóc đã bị nướng sống rồi!"
L49_1.m_Talk_VTN = L50_1
L50_1 = "如果没有我帮你控制，你现在早就变成烤乳猪了！！"
L49_1.m_Talk_SCN = L50_1
L50_1 = "Ohne mich als Unterstützung, die als Kontrolleinheit agiert, wäre aus dir schon längst ein Rollbraten geworden!"
L49_1.m_Talk_DEU = L50_1
L50_1 = "Si je n'avais pas été là, tu aurais pu être complètement calcinée !"
L49_1.m_Talk_FRA = L50_1
L50_1 = {}
