L51_1 = "RAYLEIGH_CODEX_NULL_NULL"
L50_1.m_CharStrID = L51_1
L51_1 = "고작 초콜릿 하나 더 사려고 했다가 말이야!"
L50_1.m_Talk_KOREA = L51_1
L50_1.m_fTalkTime = 0.03
L51_1 = "たかがチョコレートケーキを追加で買おうとして！"
L50_1.m_Talk_JPN = L51_1
L51_1 = "For a chocolate cake!"
L50_1.m_Talk_ENG = L51_1
L51_1 = "竟然只是因為想再買一個巧克力蛋糕！！"
