L2_1 = "그, 그치만… 이건 평범한 초콜릿이랑은 다른 걸?"
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "で、でも……これはただのチョコとは違うよ？"
L1_1.m_Talk_JPN = L2_1
L2_1 = "B-but this is no ordinary chocolate cake."
L1_1.m_Talk_ENG = L2_1
L2_1 = "可，可是…這不是普通的巧克力蛋糕。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "ต-แต่นี่ไม่ใช่เค้กช็อคโกแลตธรรมดา"
L1_1.m_Talk_THA = L2_1
L2_1 = "N-nhưng đây không phải là bánh sô cô la bình thường."
L1_1.m_Talk_VTN = L2_1
L2_1 = "但、但是……那可不是普通的巧克力啊？"
L1_1.m_Talk_SCN = L2_1
L2_1 = "A-aber ... das ist keine gewöhnliche Schokolade!"
L1_1.m_Talk_DEU = L2_1
L2_1 = "Ah, mais... Ce n'est pas un gâteau au chocolat ordinaire !"
L1_1.m_Talk_FRA = L2_1
