L2_1.m_Pos = "C"
L2_1.m_Crash = 30
L3_1 = "할로윈 한정 오싹오싹 호박 초콜릿 케이크… 그것도 민트 맛이라고!"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "ハロウィン限定のゾクゾクかぼちゃのチョコケーキ……しかもね、ミント味だよ！"
L2_1.m_Talk_JPN = L3_1
L3_1 = "It’s a Creepy Pumpkin Chocolate Cake, only sold during the Halloween... Plus, it’s mint!"
L2_1.m_Talk_ENG = L3_1
L3_1 = "是萬聖節限定的恐怖喔南瓜巧克力蛋糕…而且還是薄荷口味的！"
L2_1.m_Talk_TWN = L3_1
L3_1 = "เป็นเค้กช็อกโกแลตฟักทองน่าขนลุก มีขายเฉพาะช่วงวันฮาโลวีนเท่านั้น... แถมยังเป็นมิ้นต์ด้วย!"
L2_1.m_Talk_THA = L3_1
L3_1 = "Đó là Bánh sô cô la bí ngô đáng sợ, chỉ được bán trong dịp Halloween... Thêm vào đó, nó là bạc hà!"
L2_1.m_Talk_VTN = L3_1
L3_1 = "是万圣节限定惊悚南瓜巧克力蛋糕……而且还是薄荷味！"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Das ist der limitierte Halloween-Schokokuchen des gruseligen Kürbisgeistes ... und sogar in Minzgeschmack!"
L2_1.m_Talk_DEU = L3_1
L3_1 = "C'est un gâteau de la terrible citrouille, en édition limitée pour Halloween... Et parfumé à la menthe, en plus !"
L2_1.m_Talk_FRA = L3_1
