L4_1.m_Face = "UNIT_SURPRISE"
L5_1 = "YOONA_CODEX_NULL_NULL"
L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "C"
L4_1.m_Crash = 30
L5_1 = "아, 그래! 집에 돌아가면 레일리도 한 입 줄게!"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "あ、そうだ！　帰ったらレイリーにも一口あげる！！"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Oh, I will let you have a bite when we get home, Rayleigh!"
L4_1.m_Talk_ENG = L5_1
L5_1 = "那不然！回去後我分你一口！"
L4_1.m_Talk_TWN = L5_1
L5_1 = "โอ้ ฉันจะให้คุณกินอะไรสักคำเมื่อเรากลับถึงบ้าน เรย์ลีห์!"
L4_1.m_Talk_THA = L5_1
L5_1 = "Ồ, cháu sẽ cho ông ăn một miếng khi chúng ta về đến nhà, Rayleigh!"
L4_1.m_Talk_VTN = L5_1
L5_1 = "那好！回家之后给你吃一口就可以了吧？雷利！"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Ach, genau! Und wenn wir zuhause ankommen, kriegst du auch einen Bissen davon!"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Bon d'accord, je te donnerai une part en rentrant !"
L4_1.m_Talk_FRA = L5_1
