L7_1 = "RAYLEIGH_CODEX_NULL_NULL"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "C_D"
L7_1 = "역대 계승자 중에서 이런 멍청한 이유로 솔라코덱스를 펼친 녀석은 너밖에 없을 거다!"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "歴代継承者の中でこんなに馬鹿馬鹿しい理由でソーラーコーデックスを開いたのは\nお前だけだぞ！"
L6_1.m_Talk_JPN = L7_1
L7_1 = "This is the stupidest reason for using the Solar Codex I’ve ever heard of!"
L6_1.m_Talk_ENG = L7_1
L7_1 = "在歷代的繼承人當中，只有你是因為這個愚蠢的理由而展開太陽法典！"
L6_1.m_Talk_TWN = L7_1
L7_1 = "นี่เป็นเหตุผลที่โง่ที่สุดในการใช้ โซลาร์โคเด็กซ์ ที่ฉันเคยได้ยินมา!"
L6_1.m_Talk_THA = L7_1
L7_1 = "Đây là lý do ngu ngốc nhất khi sử dụng Solar Codex mà ta từng nghe đến!"
L6_1.m_Talk_VTN = L7_1
L7_1 = "在历代的继承者当中，用这种愚蠢的理由开启太阳法典的人，大概只有你一个吧！"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Du bist bestimmt der einzige aller Nachfahren der Geschichte, die den Solarkodex aus so einem dämlichen Grund aufschlägt!"
L6_1.m_Talk_DEU = L7_1
L7_1 = "De toute la famille, tu es la seule à avoir ouvert le codex pour une raison aussi stupide !"
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "COUNTERCASE_YUNA_NORMAL_3@107#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 107
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 30913
L7_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_3"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "RAYLEIGH_CODEX_NULL_NULL"
L7_1.m_CharStrID = L8_1
L8_1 = "메이 녀석. 용케도 이런 말썽쟁이를 후계자로 지명했군."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "メイの奴、よくもこんなおてんばを後継者に選んだな。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "I can’t believe May chose such a troublemaker as her successor."
L7_1.m_Talk_ENG = L8_1
L8_1 = "梅伊竟然找這種腦袋不靈光的傢伙來當繼承人。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ฉันไม่อยากจะเชื่อเลยว่าเมย์จะเลือกคนเจ้าปัญหาเช่นนี้มาเป็นผู้สืบทอดตำแหน่งของเธอ"
L7_1.m_Talk_THA = L8_1
L8_1 = "Ta không thể tin được May lại chọn một đứa gây rối như vậy làm người kế nhiệm."
L7_1.m_Talk_VTN = L8_1
L8_1 = "梅伊那家伙，为什么要将这样的惹事精指定为继承人。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Hach, May. Was hast du dir dabei gedacht, als du diesen Taugenichts als Nachfolgerin bestimmt hast?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "May... Pourquoi as-tu choisi cette idiote comme héritière ?"
L7_1.m_Talk_FRA = L8_1
