L12_1 = "えっ、許してくれるの？"
L11_1.m_Talk_JPN = L12_1
L12_1 = "Oh! Then you’re forgiving me?"
L11_1.m_Talk_ENG = L12_1
L12_1 = "那你可以原諒我嗎？"
L11_1.m_Talk_TWN = L12_1
L12_1 = "โอ้! คุณจะยกโทษให้ฉันเหรอ?"
L11_1.m_Talk_THA = L12_1
L12_1 = "Ồ! Thế ông có tha thứ cho cháu không?"
L11_1.m_Talk_VTN = L12_1
L12_1 = "额！那就是原谅我了吗？"
L11_1.m_Talk_SCN = L12_1
L12_1 = "Ui! Heißt das, du verzeihst mir?"
L11_1.m_Talk_DEU = L12_1
L12_1 = "Oh ! Alors tu me pardonnes ?"
L11_1.m_Talk_FRA = L12_1
