L13_1 = "COUNTERCASE_YUNA_NORMAL_3@112#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 112
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 30913
L12_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_3"
