L12_1.m_Face = "UNIT_SURPRISE"
L13_1 = "RAYLEIGH_CODEX_NULL_NULL"
L12_1.m_CharStrID = L13_1
L12_1.m_Pos = "C_D"
L13_1 = "그래. 다음부터는 조심하라고."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "ああ、次からは気をつけろよ。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Yes. And be careful next time."
L12_1.m_Talk_ENG = L13_1
L13_1 = "嗯嗯，下次注意一點。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "ใช่ และระมัดระวังในครั้งต่อไป"
L12_1.m_Talk_THA = L13_1
L13_1 = "Đúng. Và lần sau hãy cẩn thận."
L12_1.m_Talk_VTN = L13_1
L13_1 = "嗯，下次一定要注意。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Ja. Pass beim nächsten Mal besser auf."
L12_1.m_Talk_DEU = L13_1
L13_1 = "Oui. Mais sois plus prudente la prochaine fois !"
L12_1.m_Talk_FRA = L13_1
