L14_1 = "YOONA_CODEX_NULL_NULL"
L13_1.m_CharStrID = L14_1
L13_1.m_Pos = "C"
L13_1.m_Crash = 30
L14_1 = "우와! 레일리 정말 고마워! 넌 최고의 파트너야!!"
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "わあ！　本当にありがとう！　レイリーは最高の相棒だよ！！"
L13_1.m_Talk_JPN = L14_1
L14_1 = "Thank you, Rayleigh! You’re the best partner ever!"
L13_1.m_Talk_ENG = L14_1
L14_1 = "哇！謝謝瑞利！！你是最棒的夥伴！！"
L13_1.m_Talk_TWN = L14_1
L14_1 = "ขอบคุณเรย์ลีห์! คุณเป็นหุ้นส่วนที่ดีที่สุด!"
L13_1.m_Talk_THA = L14_1
L14_1 = "Cảm ơn ông, Rayleigh! Ông là người cô tốt nhất trên đời!"
L13_1.m_Talk_VTN = L14_1
L14_1 = "哇啊！雷利，谢谢你！你真的是我最好的搭档！！"
L13_1.m_Talk_SCN = L14_1
L14_1 = "Wow! Danke, Rayleigh! Du bist die beste Partnerin, die es gibt!!!"
L13_1.m_Talk_DEU = L14_1
L14_1 = "Wouah ! Merci Rayleigh ! Tu es le meilleur !"
L13_1.m_Talk_FRA = L14_1
