L15_1 = "RAYLEIGH_CODEX_NULL_NULL"
L14_1.m_CharStrID = L15_1
L14_1.m_Pos = "C_D"
L15_1 = "…에잇! 달라붙지 마! 그러다 데인다고!"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "……よせ！　べたべたするな！　火傷するぞ！"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Stay away! You’ll get burned!"
L14_1.m_Talk_ENG = L15_1
L15_1 = "…走開啦！不要靠我那麼近！會燙傷啦！"
L14_1.m_Talk_TWN = L15_1
L15_1 = "อยู่ห่าง ๆ! คุณจะถูกไฟไหม้!"
L14_1.m_Talk_THA = L15_1
L15_1 = "Tránh xa ra không bị bỏng!"
L14_1.m_Talk_VTN = L15_1
L15_1 = "……哎！别粘着我！不小心会被烫到的！"
L14_1.m_Talk_SCN = L15_1
L15_1 = "... Hmpf! Kleb nicht an mir! Sonst verbrennst du dich!"
L14_1.m_Talk_DEU = L15_1
L15_1 = "... Ah ! Ne t'approche pas ! Tu vas me brûler !"
L14_1.m_Talk_FRA = L15_1
