L20_1 = "STALKER_COUNTERCASE_NULL"
L19_1.m_CharStrID = L20_1
L20_1 = "어머나, 저 아이... 꽤 귀엽잖아?"
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "あら、あの子……なかなか可愛いじゃない。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Oh, that girl... She’s pretty cute."
L19_1.m_Talk_ENG = L20_1
L20_1 = "哇，那女孩…好可愛喔。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "โอ้ เด็กผู้หญิงคนนั้น... เธอน่ารักจังเลย"
L19_1.m_Talk_THA = L20_1
L20_1 = "Ồ, cô gái đó... Cô ấy khá dễ thương."
L19_1.m_Talk_VTN = L20_1
L20_1 = "哇啊，那个孩子……好可爱？"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Oho, dieses Mädel dort ... Ist ja ziemlich süß!"
L19_1.m_Talk_DEU = L20_1
L20_1 = "Oh ! Cette fille... est plutôt mignonne !"
L19_1.m_Talk_FRA = L20_1
