L21_1 = "COUNTERCASE_YUNA_NORMAL_3@120#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 120
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 30913
L20_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_3"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L21_1 = "STALKER_COUNTERCASE_NULL"
L20_1.m_CharStrID = L21_1
L21_1 = "싹이 보여, 이런 곳에서 숨은 원석을 발견할 줄이야. 운이 좋네."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "見どころがあるわ。こんなところで原石に出会えるとは、ついてるわね。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "I see her potential. I didn’t expect to find a hidden diamond here. What a lucky day."
L20_1.m_Talk_ENG = L21_1
L21_1 = "沒想到會在這種地方發現原石，真幸運。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ฉันเห็นศักยภาพของเธอ ฉันไม่ได้คาดหวังว่าจะพบเพชรที่ซ่อนอยู่ที่นี่ ช่างเป็นวันที่โชคดีจริงๆ"
L20_1.m_Talk_THA = L21_1
L21_1 = "Tôi nhìn thấy tiềm năng của cô ấy. Tôi không ngờ lại tìm thấy một viên kim cương ẩn giấu ở đây. Thật là một ngày may mắn."
L20_1.m_Talk_VTN = L21_1
L21_1 = "我看到了她的天分。没想到竟然能在这里找到未被打磨的原石，真是走运。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Ich sehe Potenzial. Ausgerechnet hier entdecke ich einen ungeschliffenen Diamanten. Ich Glückspilz."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Je sens qu'elle a du potentiel. Je ne pensais pas trouver une perle rare dans un endroit pareil. C'est mon jour de chance, on dirait !"
L20_1.m_Talk_FRA = L21_1
