L45_1.m_fTalkTime = 0.03
L46_1 = "そもそも強盗だろうがストーカーだろうが、関係なくない？"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Who cares if it’s a robber, or a stalker?"
L45_1.m_Talk_ENG = L46_1
L46_1 = "管他是強盜還是跟蹤狂，"
L45_1.m_Talk_TWN = L46_1
L46_1 = "ใครจะสนใจว่าเป็นโจรหรือสตอล์กเกอร์?"
L45_1.m_Talk_THA = L46_1
L46_1 = "Ai quan tâm đó là một tên cướp hay một kẻ rình rập?"
