L48_1.m_Talk_TWN = L49_1
L49_1 = "อิอิ บอกฉันเมื่อคุณต้องการความช่วยเหลือจากฉัน ฉันจะอยู่ที่นั่นเพื่อคุณ"
L48_1.m_Talk_THA = L49_1
L49_1 = "Hehe, hãy nói với tôi khi cần tôi giúp đỡ. Tôi sẽ giúp."
L48_1.m_Talk_VTN = L49_1
L49_1 = "嘿嘿，如果你害怕可以直说，我可以代你打哦。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Hehe, sag jederzeit Bescheid, wenn du mich brauchst. Dann kämpfe ich an deiner Stelle."
L48_1.m_Talk_DEU = L49_1
L49_1 = "Si tu as peur, je peux me battre à ta place..."
