L3_1 = "UNIT_DESPAIR"
L2_1.m_Face = L3_1
L2_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L3_1 = "L_M_I"
L2_1.m_Pos = L3_1
L3_1 = "라우라는 어떻게 생각해?"
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "ラウラはどう思う？"
L2_1.m_Talk_JPN = L3_1
L3_1 = "What do you think, Laura?"
L2_1.m_Talk_ENG = L3_1
L3_1 = "那蘿拉覺得呢？"
L2_1.m_Talk_TWN = L3_1
L3_1 = "คุณคิดยังไงลอร่า?"
L2_1.m_Talk_THA = L3_1
L3_1 = "Cô nghĩ gì thế Laura?"
L2_1.m_Talk_VTN = L3_1
L3_1 = "劳拉你也这么认为吗？"
L2_1.m_Talk_SCN = L3_1
L3_1 = "Und was sagst du dazu, Laura?"
L2_1.m_Talk_DEU = L3_1
L3_1 = "Et toi Laura, qu'est-ce que tu en penses ?"
L2_1.m_Talk_FRA = L3_1
