L4_1 = "COUNTERCASE_YUNA_NORMAL_3@153#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 153
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 30913
L3_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_3"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Face = "UNIT_PRIDE"
L3_1.m_CharStrID = "LAURA_STREGA_EVENT_NULL"
L3_1.m_Pos = "R"
L4_1 = "…흥, 자업자득이지, 뭐."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "……ふん。自業自得だろ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "I’d say she brought it on herself."
L3_1.m_Talk_ENG = L4_1
L4_1 = "…哼，你活該。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "ฉันว่าเธอเอามันมาเอง"
L3_1.m_Talk_THA = L4_1
L4_1 = "Ta muốn nói rằng cô ấy đã tự chuốc lấy nó."
L3_1.m_Talk_VTN = L4_1
L4_1 = "……哼，应该说自作自受吧。"
L3_1.m_Talk_SCN = L4_1
L4_1 = "... Hmpf. Selbst schuld."
L3_1.m_Talk_DEU = L4_1
L4_1 = "Je n'ai qu'une chose à dire : qui sème le vent récolte la tempête."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "COUNTERCASE_YUNA_NORMAL_3@154#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 154
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 30913
L4_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_3"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "LAURA_STREGA_EVENT_NULL"
L4_1.m_Pos = "R"
L5_1 = "그러게 누가 그런 멍청한 짓을 하래? 마녀가 돼서 남들 눈에 띄면 어쩌자는 거야?"
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "毎度バカなことをやってるからだろう。魔女のくせに目立ってどうするって言うんだ。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "It was a stupid thing to do. A witch shouldn’t draw attention to herself!"
L4_1.m_Talk_ENG = L5_1
L5_1 = "誰叫你要做那種愚蠢的事？要是被人發現你是魔女，你打算怎麼辦？"
L4_1.m_Talk_TWN = L5_1
L5_1 = "มันเป็นสิ่งที่โง่ที่จะทำ แม่มดไม่ควรดึงความสนใจมาที่ตัวเอง!"
L4_1.m_Talk_THA = L5_1
L5_1 = "Đó là một điều ngu ngốc. Một phù thủy không nên thu hút sự chú ý vào mình!"
L4_1.m_Talk_VTN = L5_1
L5_1 = "谁让你做那些白痴的事情啊？作为魔女，就应该低调不被人发现吧？"
L4_1.m_Talk_SCN = L5_1
L5_1 = "Wer tut auch so was Trotteliges? Eine Hexe hat nichts Gutes davon, in der Öffentlichkeit aufzufallen!"
L4_1.m_Talk_DEU = L5_1
L5_1 = "Qui t'a dit d'agir de manière aussi stupide ? Tu es une sorcière je te rappelle ! Il ne fallait pas te faire remarquer."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
