L7_1 = "COUNTERCASE_YUNA_NORMAL_3@156#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 156
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 30913
L6_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_3"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_LAUGH"
L6_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L6_1.m_Pos = "C"
L7_1 = "어머, 우리가 떳떳하게 할 말은 아닌 거 같은데, 라우라?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "あら、私たちが堂々と言えたことじゃないわよ、ラウラ。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Oh, we’re not really in any position to say that, Laura."
L6_1.m_Talk_ENG = L7_1
L7_1 = "哎呀，蘿拉你不要這麼兇啦。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "โอ้ เราไม่สามารถพูดแบบนั้นได้จริงๆ ลอร่า"
L6_1.m_Talk_THA = L7_1
L7_1 = "Ồ, chúng ta thực sự không có tư cách để nói điều đó, Laura."
L6_1.m_Talk_VTN = L7_1
L7_1 = "呃……这种话我们也没资格说吧，劳拉？"
L6_1.m_Talk_SCN = L7_1
L7_1 = "Oha, aber Laura, wir können es uns kaum erlauben, so etwas zu sagen."
L6_1.m_Talk_DEU = L7_1
L7_1 = "Je ne sais pas si nous sommes les mieux placées pour dire ce genre de choses, Laura..."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "COUNTERCASE_YUNA_NORMAL_3@157#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 157
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 30913
L7_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_3"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L8_1 = "UNIT_SERIOUS"
L7_1.m_Face = L8_1
L7_1.m_CharStrID = "EVELYN_STREGA_NULL_NULL"
L7_1.m_Pos = "C"
L8_1 = "어쨌든 다 같이 생각해보자. 생각보다 심각한 일일 지도 모르니까."
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "とにかくみんなで考えてみましょう。殊の外深刻な事態かもしれないわ。"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Anyway, let’s discuss this together. It could be a serious situation."
L7_1.m_Talk_ENG = L8_1
L8_1 = "總之大家一起想想辦法吧。這件事說不定比想像中還要嚴重呢。"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ยังไงก็มาหารือเรื่องนี้ด้วยกัน มันอาจเป็นสถานการณ์ที่ร้ายแรง"
L7_1.m_Talk_THA = L8_1
L8_1 = "Dù sao đi nữa, chúng ta hãy cùng nhau thảo luận về vấn đề này. Đó có thể là một tình huống nghiêm trọng."
L7_1.m_Talk_VTN = L8_1
L8_1 = "总之，一起想办法吧。事情可能比想象中的严重也说不定。"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Lasst uns zusammen überlegen. Es könnte ernster sein, als wir denken."
L7_1.m_Talk_DEU = L8_1
L8_1 = "Quoi qu'il en soit, nous devons trouver une solution. C'est peut-être plus grave qu'on ne le pense."
L7_1.m_Talk_FRA = L8_1
L8_1 = {}
