L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 162
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 30913
L12_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_3"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_CharStrID = "LAURA_STREGA_EVENT_NULL"
L12_1.m_Pos = "L"
L13_1 = "네가 솔라코덱스를 사용하는 걸 보고, 그걸 훔치려는 녀석일지도 모르지."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "ソーラーコーデックスを使う汝を見て、それを盗もうとする愚か者かもしれん。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "Maybe this person saw you using the Solar Codex, and wants to steal it."
L12_1.m_Talk_ENG = L13_1
L13_1 = "說不定那個人是看到你使用太陽法典，就想來把它偷走。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "บางทีคนๆ นี้อาจจะเห็นคุณใช้ โซลาร์โคเด็กซ์ และต้องการขโมยมัน"
L12_1.m_Talk_THA = L13_1
L13_1 = "Có thể người này đã nhìn thấy nhóc sử dụng Solar Codex và muốn đánh cắp nó."
L12_1.m_Talk_VTN = L13_1
L13_1 = "可能是看到你使用太阳法典，想要来窃取的家伙也说不定。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "Vielleicht will jemand den Solarkodex stehlen, weil er gesehen hat, wie du ihn benutzt."
L12_1.m_Talk_DEU = L13_1
L13_1 = "C'est peut-être quelqu'un qui t'a vu te servir du Codex solaire et qui voudrait te le voler."
L12_1.m_Talk_FRA = L13_1
