L14_1.m_Pos = "C"
L14_1.m_Crash = 30
L15_1 = "솔라코덱스를… 훔쳐?"
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "ソーラーコーデックスを……盗む？"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Steal my Solar Codex?"
L14_1.m_Talk_ENG = L15_1
L15_1 = "偷走…太陽法典？"
L14_1.m_Talk_TWN = L15_1
L15_1 = "ขโมย โซลาร์โคเด็กซ์ ของฉันเหรอ?"
L14_1.m_Talk_THA = L15_1
L15_1 = "Ăn cắp Solar Codex của cháu?"
L14_1.m_Talk_VTN = L15_1
L15_1 = "窃取太阳法典……？"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Den Solarkodex ... stehlen?"
L14_1.m_Talk_DEU = L15_1
L15_1 = "Voler le Codex solaire ?"
L14_1.m_Talk_FRA = L15_1
