L15_1.m_CutScenKey_Talk = L16_1
L16_1 = 165
L15_1.m_CutScenProcessKey = L16_1
L15_1.m_CutScenID = 30913
L15_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_3"
