L16_1 = "UNIT_DESPAIR"
L15_1.m_Face = L16_1
L15_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L15_1.m_Pos = "C"
L16_1 = "그, 그치만 솔라코덱스에 깃든 힘은 태양의 대마녀만 다룰 수 있잖아."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "で、でもソーラーコーデックスに宿る力は、太陽の大魔女じゃないと制御できないでしょ？"
L15_1.m_Talk_JPN = L16_1
L16_1 = "B-but only the Great Witch of the Sun can use the Solar Codex, right?"
L15_1.m_Talk_ENG = L16_1
L16_1 = "可，可是不是只有大魔女可以控制太陽法典的力量嗎？"
L15_1.m_Talk_TWN = L16_1
L16_1 = "ข-แต่มีเพียงแม่มดผู้ยิ่งใหญ่แห่งดวงอาทิตย์เท่านั้นที่สามารถใช้ โซลาร์โคเด็กซ์ ได้ใช่ไหม"
L15_1.m_Talk_THA = L16_1
L16_1 = "N-nhưng chỉ có Phù thủy Mặt trời Vĩ Đại mới có thể sử dụng Solar Codex, phải không?"
L15_1.m_Talk_VTN = L16_1
L16_1 = "但、但是太阳法典中的力量，不是只有太阳大魔女才能使用吗？"
L15_1.m_Talk_SCN = L16_1
L16_1 = "A-aber die Kraft, die im Solarkodex liegt, kann doch nur von der Großen Hexe der Sonne beherrscht werden."
L15_1.m_Talk_DEU = L16_1
L16_1 = "Mais seule la Grande sorcière du soleil peut contrôler le pouvoir du codex, non ?"
L15_1.m_Talk_FRA = L16_1
L16_1 = {}
L17_1 = "COUNTERCASE_YUNA_NORMAL_3@166#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 166
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 30913
L16_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_3"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_CharStrID = "YOONA_STREGA_NULL_NULL"
L16_1.m_Pos = "C"
L17_1 = "소유자를 불태우는 책을 훔쳐서 뭐하게?"
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "使い手まで燃やしてしまう本を盗んでどうするの？"
L16_1.m_Talk_JPN = L17_1
L17_1 = "Who would want a book that burns anyone who holds it?"
L16_1.m_Talk_ENG = L17_1
L17_1 = "那個人沒事偷走一本會把自己燒焦的書要幹嘛？"
L16_1.m_Talk_TWN = L17_1
L17_1 = "ใครจะอยากได้หนังสือที่เผาใครก็ตามที่ถือมัน?"
L16_1.m_Talk_THA = L17_1
L17_1 = "Ai lại muốn một cuốn sách có thể đốt cháy bất cứ ai cầm nó?"
L16_1.m_Talk_VTN = L17_1
L17_1 = "为什么要窃取会焚烧使用者的书啊？"
L16_1.m_Talk_SCN = L17_1
L17_1 = "Wozu ein Buch stehlen, das den Inhaber verbrennt?"
L16_1.m_Talk_DEU = L17_1
L17_1 = "Pourquoi vouloir voler un livre qui vous brûlerait les mains ?"
L16_1.m_Talk_FRA = L17_1
