L20_1 = "COUNTERCASE_YUNA_NORMAL_3@169#Talk"
L19_1.m_CutScenKey_Talk = L20_1
L20_1 = 169
L19_1.m_CutScenProcessKey = L20_1
L19_1.m_CutScenID = 30913
L19_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_3"
L19_1.m_bWaitClick = true
L19_1.m_fWaitTime = 0
L19_1.m_Face = "UNIT_PRIDE"
L19_1.m_CharStrID = "LAURA_STREGA_EVENT_NULL"
L19_1.m_Pos = "L"
L20_1 = "당연히 훔치려는 쪽이 우리만 알고 있는 자세한 사정 따위를 알고 있을 리가 없지."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "それは妾たちだけが知っていることで、盗もうとしてるやつが知らなくても当然だろう。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "You can’t expect a thief to know such details."
L19_1.m_Talk_ENG = L20_1
L20_1 = "那個想偷的人怎麼會知道這些事。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "คุณไม่สามารถคาดหวังให้ขโมยรู้รายละเอียดดังกล่าวได้"
L19_1.m_Talk_THA = L20_1
L20_1 = "Tên trộm làm sao biết được những chi tiết như vậy."
L19_1.m_Talk_VTN = L20_1
L20_1 = "当然是窃取者不知道这些只有我们知晓的详细情况啊。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "Der Dieb hat eben keine Ahnung über diese Art von Details, die nur wir kennen."
L19_1.m_Talk_DEU = L20_1
L20_1 = "Peut-être que notre homme n'a pas toutes les informations..."
L19_1.m_Talk_FRA = L20_1
L20_1 = {}
L21_1 = "COUNTERCASE_YUNA_NORMAL_3@170#Talk"
L20_1.m_CutScenKey_Talk = L21_1
L21_1 = 170
L20_1.m_CutScenProcessKey = L21_1
L20_1.m_CutScenID = 30913
L20_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_3"
L20_1.m_bWaitClick = true
L20_1.m_fWaitTime = 0
L20_1.m_CharStrID = "LAURA_STREGA_EVENT_NULL"
L20_1.m_Pos = "L"
L21_1 = "세상에는 아티팩트만 보면, 눈 돌아가는 트레져 헌터 같은 녀석들도 잔뜩 있다고."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "世の中にはアーティファクトに目が眩んだトレジャーハンターみたいな連中が\nいっぱいいるんだ。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "There are a lot of treasure hunters who just go crazy when they see an Artifact."
L20_1.m_Talk_ENG = L21_1
L21_1 = "只要有人造神器，就會有許多虎視眈眈的人。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "มีนักล่าสมบัติมากมายที่คลั่งไคล้เมื่อเห็นสิ่งประดิษฐ์"
L20_1.m_Talk_THA = L21_1
L21_1 = "Có rất nhiều thợ săn kho báu phát điên khi nhìn thấy một Thần Khí."
L20_1.m_Talk_VTN = L21_1
L21_1 = "世界上有很多人就像是贪婪的淘金者，看到人造神器就会铤而走险。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "In der Welt gibt es eine Menge Leute wie etwa Schatzjäger, die ganz wild nach Artefakten sind."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Après tout, ce n'est pas rare de voir des chasseurs de trésors qui perdent toute faculté de discernement devant une relique rare !"
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "COUNTERCASE_YUNA_NORMAL_3@171#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 171
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 30913
L21_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_3"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L21_1.m_CharStrID = "LAURA_STREGA_EVENT_NULL"
L21_1.m_Pos = "L"
L22_1 = "어쩌면 널 따라다니는 녀석은 그 책을 키가 커지는 아티팩트쯤으로 착각하고 있을지도 몰라."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "もしかしたら、汝のストーカーはその本を身長が伸びる程度のアーティファクトだと\n勘違いしているかもしれない。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Maybe this stalker thinks your book is an Artifact that makes you taller."
L21_1.m_Talk_ENG = L22_1
L22_1 = "說不定那個跟蹤你的人以為那本書是可以長高的人造神器。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "บางทีสตอล์กเกอร์คนนี้อาจคิดว่าหนังสือของคุณเป็นสิ่งประดิษฐ์ที่ทำให้คุณสูงขึ้น"
L21_1.m_Talk_THA = L22_1
L22_1 = "Có thể kẻ theo dõi này nghĩ rằng cuốn sách của nhóc là một Thần Khí giúp nhóc cao hơn."
L21_1.m_Talk_VTN = L22_1
L22_1 = "说不定跟踪你的人认为，太阳法典是能让人长高的人造神器也说不定。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Es könnte sein, dass dein Stalker das Buch für ein Artefakt hält, das einen größer macht."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Peut-être que celui qui te suit pense qu'il s'agit simplement d'un livre qui permet d'accroître la croissance..."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
