L23_1.m_fTalkTime = 0.03
L24_1 = "……し、身長が伸びるアーティファクト？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "An Artifact that makes you taller?"
L23_1.m_Talk_ENG = L24_1
L24_1 = "長高的…人造神器？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "สิ่งประดิษฐ์ที่ทำให้คุณสูงขึ้นเหรอ?"
L23_1.m_Talk_THA = L24_1
L24_1 = "Một Thần Khí giúp cao hơn?"
L23_1.m_Talk_VTN = L24_1
L24_1 = "……让人长高的人造神器？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "... E-ein Artefakt, das einen größer macht?"
L23_1.m_Talk_DEU = L24_1
L24_1 = "Un artefact qui accroît la croissance ?"
