L26_1.m_Pos = "L"
L27_1 = "혹시 또 모르지. 계승자인 너와 솔라코덱스를 떼어놓는 것 자체가 목적일지도."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "もしくは、継承者である汝とソーラーコーデックスを引き離すことが目的かもしれない。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "Who knows? Maybe they want to separate you from the Solar Codex."
L26_1.m_Talk_ENG = L27_1
L27_1 = "誰知道？說不定也有可能是要把身為繼承人的你和太陽法典分開。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "ใครจะรู้? บางทีพวกเขาต้องการแยกคุณออกจากโซลาร์โคเด็กซ์"
L26_1.m_Talk_THA = L27_1
L27_1 = "Ai biết? Có lẽ chúng muốn tách nhóc khỏi Solar Codex."
L26_1.m_Talk_VTN = L27_1
L27_1 = "或者有其他的目的呢。比如，想要将作为继承人的你和太阳法典分开。"
L26_1.m_Talk_SCN = L27_1
L27_1 = "Oder wer weiß? Vielleicht beabsichtigt jemand, dir das Solarkodex wegzunehmen, weil du die Nachfolgerin bist."
L26_1.m_Talk_DEU = L27_1
L27_1 = "Qui sait ? Ou peut-être qu'il cherche à te déposséder du Codex, toi qui en es pourtant la digne héritière..."
L26_1.m_Talk_FRA = L27_1
