L36_1 = "…어라? 아직 오픈 시간 조금 남지 않았어?"
L35_1.m_Talk_KOREA = L36_1
L35_1.m_fTalkTime = 0.03
L36_1 = "……あれ？　開店まではまだ時間があるよね。"
L35_1.m_Talk_JPN = L36_1
L36_1 = "Eh? I thought we had some time left before the shop opened."
L35_1.m_Talk_ENG = L36_1
L36_1 = "…奇怪？又還沒到開店時間？"
L35_1.m_Talk_TWN = L36_1
L36_1 = "เอ๊ะ? ฉันคิดว่าเราเหลือเวลาอีกสักพักก่อนที่ร้านจะเปิด"
L35_1.m_Talk_THA = L36_1
L36_1 = "Hở? Tôi tưởng vẫn còn sớm, cửa hàng chưa mở cửa mà."
L35_1.m_Talk_VTN = L36_1
L36_1 = "……哎呀？营业时间不是还没到吗？"
L35_1.m_Talk_SCN = L36_1
L36_1 = "... Huch? Wir öffnen doch erst nach einer Weile?"
L35_1.m_Talk_DEU = L36_1
L36_1 = "Tiens ? C'est déjà l'heure d'ouvrir ?"
L35_1.m_Talk_FRA = L36_1
L36_1 = {}
