L37_1 = "……서 설마, 그 스토커가?"
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "……ま、まさか、ストーカー？"
L36_1.m_Talk_JPN = L37_1
L37_1 = "C-could it be the stalker?"
L36_1.m_Talk_ENG = L37_1
L37_1 = "…難…難道是那個跟蹤狂？"
L36_1.m_Talk_TWN = L37_1
L37_1 = "ค-อาจจะเป็นสตอล์กเกอร์เหรอ?"
