L41_1.m_Crash = 30
L42_1 = "…어머, 뒷모습이 보여서 따라왔는데."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "……あら、後ろ姿が見えたので付いてきたのですが。"
L41_1.m_Talk_JPN = L42_1
L42_1 = "Oh, I saw you from behind and followed you."
L41_1.m_Talk_ENG = L42_1
L42_1 = "…哈囉，我看到你的背影所以就跟上來。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "โอ้ ฉันเห็นคุณจากด้านหลังและติดตามคุณไป"
L41_1.m_Talk_THA = L42_1
L42_1 = "Ồ, tôi nhìn thấy cô từ phía sau nên đi theo cô."
L41_1.m_Talk_VTN = L42_1
L42_1 = "……哎呀，我是看到背影后一直追过来的。"
L41_1.m_Talk_SCN = L42_1
L42_1 = "... Oh! Ich bin dir gefolgt, weil ich dich von hinten gesehen habe."
L41_1.m_Talk_DEU = L42_1
L42_1 = "Oh, pardon... Je n'ai pas pu m'empêcher de vous suivre !"
L41_1.m_Talk_FRA = L42_1
L42_1 = {}
L43_1 = "COUNTERCASE_YUNA_NORMAL_3@192#Talk"
L42_1.m_CutScenKey_Talk = L43_1
L43_1 = 192
L42_1.m_CutScenProcessKey = L43_1
L42_1.m_CutScenID = 30913
