L42_1.m_Face = "UNIT_LAUGH"
L43_1 = "CHOIENA_HB_NULL_NULL"
L42_1.m_CharStrID = L43_1
L42_1.m_Pos = "C"
L43_1 = "어쩜, 다시 봐도 동생 분… 언니랑 정말 닮으셨네요."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "妹さんだったのですか。お姉さんにそっくりですね。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "You do look like your sister."
L42_1.m_Talk_ENG = L43_1
L43_1 = "你…和姊姊長得很像呢。"
L42_1.m_Talk_TWN = L43_1
L43_1 = "คุณดูเหมือนน้องสาวของคุณ"
L42_1.m_Talk_THA = L43_1
L43_1 = "Cô trông giống chị gái mình thật."
L42_1.m_Talk_VTN = L43_1
L43_1 = "没想到妹妹……也和姐姐长得这么像。"
L42_1.m_Talk_SCN = L43_1
L43_1 = "Hach, ich muss wirklich sagen, dass du wirklich ... genauso aussiehst wie deine ältere Schwester!"
L42_1.m_Talk_DEU = L43_1
L43_1 = "C'est que... Vous êtes le portrait craché de votre grande sœur."
L42_1.m_Talk_FRA = L43_1
