L47_1 = "COUNTERCASE_YUNA_NORMAL_3@196#Talk"
L46_1.m_CutScenKey_Talk = L47_1
L47_1 = 196
L46_1.m_CutScenProcessKey = L47_1
L46_1.m_CutScenID = 30913
L46_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_3"
L46_1.m_bWaitClick = true
L46_1.m_fWaitTime = 0
L46_1.m_Face = "UNIT_IDLE"
L47_1 = "CHOIENA_HB_NULL_NULL"
L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "L"
L47_1 = "아하, 그게…… 얼마전에 우연히 놀이 공원에서 언니 분을 보고 잠재성을 느꼈거든요."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "ええ、それが……数日前、遊園地でお姉さんを偶然見かけまして、\nポテンシャルを感じたのです。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "Oh, you see... I saw your sister at the amusement park, and I saw potential in her."
L46_1.m_Talk_ENG = L47_1
L47_1 = "哈哈，是這樣的……我之前在遊樂園看到你姊姊，覺得她很有潛力。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "โอ้ คุณเห็นไหม... ฉันเห็นน้องสาวของคุณที่สวนสนุก และฉันเห็นศักยภาพในตัวเธอ"
L46_1.m_Talk_THA = L47_1
L47_1 = "Ồ,... Tôi đã gặp chị gái cô ở công viên giải trí, và tôi nhìn thấy tiềm năng ở cô ấy."
L46_1.m_Talk_VTN = L47_1
L47_1 = "啊哈，是这样……之前我偶然在游乐园看到了你姐姐，发现了她的潜力。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "Oh ja, das ist so ... Neulich habe ich zufällig deine Schwester im Themenpark gesehen und ein großes Potenzial in ihr gesehen."
L46_1.m_Talk_DEU = L47_1
L47_1 = "Ah, en fait... J'ai vu votre grande sœur par hasard au parc d'attraction, et j'ai été éblouie par son potentiel."
L46_1.m_Talk_FRA = L47_1
L47_1 = {}
L48_1 = "COUNTERCASE_YUNA_NORMAL_3@197#Talk"
L47_1.m_CutScenKey_Talk = L48_1
L48_1 = 197
L47_1.m_CutScenProcessKey = L48_1
L47_1.m_CutScenID = 30913
L47_1.m_CutScenStrID = "COUNTERCASE_YUNA_NORMAL_3"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L48_1 = "CHOIENA_HB_NULL_NULL"
L47_1.m_CharStrID = L48_1
L47_1.m_Pos = "L"
L48_1 = "탄탄한 복근에… 늘씬한 몸매… 그리고 과감한 복장도 소화할 수 있는 능숙한 분위기까지!"
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "逞しい腹筋……すらりとした体形……そして大胆な衣装も着こなせる色っぽい雰囲気！"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Her tight abs, slender figure... and a mature allure that will go well with a bold outfit!"
L47_1.m_Talk_ENG = L48_1
L48_1 = "她不只有馬甲線…身材又高挑…還可以駕馭任何大膽的服裝！"
L47_1.m_Talk_TWN = L48_1
L48_1 = "หน้าท้องแบนราบของเธอ หุ่นเพรียว... และเสน่ห์แบบผู้ใหญ่ที่เข้ากันได้ดีกับเสื้อผ้าตัวหนา!"
L47_1.m_Talk_THA = L48_1
L48_1 = "Cơ bụng săn chắc, dáng người mảnh mai... và vẻ quyến rũ trưởng thành sẽ rất hợp với bộ trang phục táo bạo!"
L47_1.m_Talk_VTN = L48_1
L48_1 = "结实的腹肌……修长的身材……还有能驾驭大尺度服装的气质！"
L47_1.m_Talk_SCN = L48_1
L48_1 = "Eine straffe Taille ... schlanke Figur ... und ein verwegener Charme, der gut zu gewagter Kleidung passt!"
L47_1.m_Talk_DEU = L48_1
L48_1 = "Elle avait la silhouette svelte et athlétique... Oh, et elle portait un costume extravagant qui lui allait à merveille !"
L47_1.m_Talk_FRA = L48_1
L48_1 = {}
