L49_1 = "CHOIENA_HB_NULL_NULL"
L48_1.m_CharStrID = L49_1
L48_1.m_Pos = "L"
L49_1 = "저와 함께라면 분명히 멋진 아이돌이 되실 수 있을 거예요."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "私と一緒なら、きっとトップアイドルになれます。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "I’m sure she will become a superstar if she works with me."
L48_1.m_Talk_ENG = L49_1
L49_1 = "我可以讓她成為大明星喔。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "ฉันแน่ใจว่าเธอจะกลายเป็นซุปเปอร์สตาร์ถ้าเธอทำงานร่วมกับฉัน"
L48_1.m_Talk_THA = L49_1
L49_1 = "Tôi chắc chắn cô ấy sẽ trở thành siêu sao nếu làm việc với tôi."
L48_1.m_Talk_VTN = L49_1
L49_1 = "如果有我的帮助，一定可以成为优秀的偶像艺人。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "Zusammen mit mir kann sie garantiert ein großer Popstar werden."
L48_1.m_Talk_DEU = L49_1
L49_1 = "J'ai tout de suite senti que je pourrais faire d'elle une star !"
L48_1.m_Talk_FRA = L49_1
