L8_1 = "네, 맞아요! 언니 분께 그 명함 꼭 좀 전해 주시겠어요?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "はい、そうです！　私の名刺、お姉さんにぜひ渡していただけますか？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Yes! Could you please pass my card on to your sister?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "沒錯！請你一定要將我的名片轉交給姊姊喔！"
L7_1.m_Talk_TWN = L8_1
L8_1 = "ใช่! คุณช่วยส่งนามบัตรของฉันไปให้น้องสาวของคุณหน่อยได้ไหม?"
L7_1.m_Talk_THA = L8_1
L8_1 = "Đúng! cô có thể vui lòng chuyển thẻ của tôi cho chị gái cô được không?"
L7_1.m_Talk_VTN = L8_1
L8_1 = "嗯，没错！能把我的名片转交给你姐姐吗？"
L7_1.m_Talk_SCN = L8_1
L8_1 = "Ja, genau! Gibst du die Visitenkarte bitte unbedingt an deine Schwester weiter?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Exactement ! Vous voulez bien transmettre ma carte à votre grande sœur ?"
L7_1.m_Talk_FRA = L8_1
