L18_1 = "후후, 그래도 본판이 귀여우니까, 솔라코덱스의 힘이 더 돋보이는 거 아닐까?"
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "ふふ。きっと素材が可愛いからソーラーコーデックスの力も活かせるんじゃない？"
L17_1.m_Talk_JPN = L18_1
L18_1 = "Oh, you’re pretty yourself. The Solar Codex only helps you stand out."
L17_1.m_Talk_ENG = L18_1
L18_1 = "呵呵，至少你本人是可愛的，再加上太陽法典的加持？"
L17_1.m_Talk_TWN = L18_1
L18_1 = "โห ตัวเองก็สวยนะ โซลาร์โคเด็กซ์ ช่วยให้คุณโดดเด่นเท่านั้น"
L17_1.m_Talk_THA = L18_1
L18_1 = "Ồ, chính Yuna cũng xinh đẹp mà. Solar Codex chỉ giúp cháu nổi bật thôi."
L17_1.m_Talk_VTN = L18_1
L18_1 = "哈哈。至少是因为本体可爱，才能凸显出太阳法典的力量吧？"
L17_1.m_Talk_SCN = L18_1
L18_1 = "Hoho, aber du bist eben in Originalform schon süß. Der Solarkodex unterstreicht das nur, würde ich sagen!"
L17_1.m_Talk_DEU = L18_1
L18_1 = "Ha ha. Mais si la Yuna du Codex solaire s'est fait remarquer, c'est parce que le modèle original est mignon, tu ne crois pas ?"
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
