L19_1 = "Evelyn, don’t make me blush."
L18_1.m_Talk_ENG = L19_1
L19_1 = "伊芙琳姊姊討厭…一直灌我迷湯。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "อีฟลิน อย่าทำให้ฉันหน้าแดงนะ"
L18_1.m_Talk_THA = L19_1
L19_1 = "Evelyn, đừng làm cháu đỏ mặt."
L18_1.m_Talk_VTN = L19_1
L19_1 = "哎呀，伊芙琳姐姐……别取笑我了。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Ach, Evelyn, bitte ... D-du schmeichelst mir!"
L18_1.m_Talk_DEU = L19_1
L19_1 = "Mais non, Evelyn... Vous allez me faire rougir."
L18_1.m_Talk_FRA = L19_1
