L21_1 = "……ふん、くだらん。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Hmpf, it’s not fun at all."
L20_1.m_Talk_ENG = L21_1
L21_1 = "……哼，無聊。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "ฮึ่ม มันไม่สนุกเลย"
L20_1.m_Talk_THA = L21_1
L21_1 = "Hừm, chẳng vui chút nào cả."
L20_1.m_Talk_VTN = L21_1
L21_1 = "……哼，真无聊。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "... Hmpf, wie langweilig."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Bah, n'importe quoi !"
