L21_1.m_Pos = "C"
L22_1 = "별 것도 아닌 일에 우쭐하긴. 너 때문에 괜히 시간만 날렸잖아."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "大したことでもないのに舞い上がるとは。汝のせいで開店準備が遅れたぞ。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "Don’t get all snippy. So, it was all a waste of time after all."
L21_1.m_Talk_ENG = L22_1
L22_1 = "有什麼了不起的，浪費大家的時間。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "อย่าแซวไปซะหมด ดังนั้นมันจึงเป็นการเสียเวลาทั้งหมด"
L21_1.m_Talk_THA = L22_1
L22_1 = "Đừng quá vội vàng. Vì vậy, rốt cuộc tất cả chỉ là lãng phí thời gian."
L21_1.m_Talk_VTN = L22_1
L22_1 = "又不是什么了不起的事情，有什么可骄傲的。因为你浪费大家这么多时间。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "Sei mal nicht so stolz über etwas so Belangloses. Deinetwegen haben wir nur Zeit verschwendet."
L21_1.m_Talk_DEU = L22_1
L22_1 = "Quelle perte de temps ! Je ne vois pas pourquoi se monter la tête avec ce genre de choses."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
