L26_1 = "어머나, 우리 라우라가 왜 이렇게 심통이 났을까?"
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "あら、どうしてご機嫌斜めなのかしら、ラウラ？"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Aww, Laura. Why are you being so mean?"
L25_1.m_Talk_ENG = L26_1
L26_1 = "哎呀呀，蘿拉幹嘛不開心啊？"
L25_1.m_Talk_TWN = L26_1
L26_1 = "อุ๊ย ลอร่า ทำไมคุณถึงใจร้ายขนาดนี้?"
L25_1.m_Talk_THA = L26_1
L26_1 = "Ôi, Laura. Tại sao lại khó tính thế?"
L25_1.m_Talk_VTN = L26_1
L26_1 = "哎呦，我们的劳拉嫉妒了吧？"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Hach, warum ist unsere liebe Laura denn so stinkig?"
L25_1.m_Talk_DEU = L26_1
L26_1 = "Pourquoi tant de colère, Laura ?"
L25_1.m_Talk_FRA = L26_1
